Answer $j$ of student $i$ belongs to question number $(i + j) \bmod 10$, so it must be compared with `key[(i + j) % 10]`.

```cpp
#include <iostream>
using namespace std;

int main() {
    char student_ans[8][10] = {
        {'A','B','A','C','C','D','E','E','A','D'},
        {'D','B','A','B','C','A','E','E','A','D'},
        {'E','D','D','A','C','B','E','E','A','D'},
        {'C','B','A','E','D','C','E','E','A','D'},
        {'A','B','D','C','C','D','E','E','A','D'},
        {'B','B','E','C','C','D','E','E','A','D'},
        {'B','B','A','C','C','D','E','E','A','D'},
        {'E','B','E','C','C','D','E','E','A','D'}
    };
    char key[10] = {'D','B','D','C','C','D','A','E','A','D'};

    for (int i = 0; i < 8; i++) {
        int correct = 0;
        for (int j = 0; j < 10; j++) {
            if (key[(i + j) % 10] == student_ans[i][j]) {
                correct++;
            }
        }
        cout << "Student " << i << "'s correct count is " << correct << endl;
    }
    return 0;
}
```

