```cpp
class Stack {
private:
    int total;
    int *arr;
    int tos;

public:
    Stack(int cap) {
        total = cap;
        arr = new int[total];
        tos = -1;
    }

    // Insertion
    void push(int item) {
        if (isFull()) {
            cout << "Full";
            return;
        }
        tos++;
        arr[tos] = item;
    }

    // Deletion
    int pop() {
        if (isEmpty()) {
            cout << "Empty";
            return -1;
        }
        int temp = arr[tos];
        arr[tos] = 0;
        tos--;
        return temp;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Empty";
            return -1;
        }
        return arr[tos];
    }

    int size() { return tos + 1; }

    bool isEmpty() { return size() == 0; }

    bool isFull() { return size() == total; }

    void display() {
        for (int i = tos; i >= 0; i--) {
            cout << arr[i] << endl;
        }
    }
};
```

Scan the string once with a stack of characters:

- Characters other than brackets are ignored.
- If the stack is non-empty and the current closing bracket matches the bracket on top, pop it.
- Otherwise push the current bracket.
- At the end the string is balanced exactly when the stack is empty.

```cpp
bool balanced(string expr) {
    stack<char> temp;
    for (int i = 0; i < expr.length(); i++) {
        char c = expr[i];
        if (c != '(' && c != ')' && c != '[' && c != ']' && c != '{' && c != '}')
            continue;                       // ignore variables and operators
        if (!temp.empty() &&
            ((temp.top() == '(' && c == ')') ||
             (temp.top() == '[' && c == ']') ||
             (temp.top() == '{' && c == '}'))) {
            temp.pop();
        } else {
            temp.push(c);
        }
    }
    if (temp.empty()) {
        return true;
    }
    return false;
}
```

```cpp
class twoStacks {
    int *a, len, top1, top2;

public:
    twoStacks(int n) {
        len = n;
        a = new int[n];
        top1 = -1;
        top2 = len;
    }

    void push1(int n) {
        if (top1 < top2 - 1) {
            top1++;
            a[top1] = n;
        } else {
            cout << "overflow";
        }
    }

    int pop1() {
        if (top1 >= 0) {
            int n = a[top1];
            top1--;
            return n;
        } else {
            cout << "underflow";
            return -1;
        }
    }

    void push2(int n) {
        if (top1 < top2 - 1) {
            top2--;
            a[top2] = n;
        } else {
            cout << "overflow";
        }
    }

    int pop2() {
        if (top2 < len) {
            int n = a[top2];
            top2++;
            return n;
        } else {
            cout << "underflow";
            return -1;
        }
    }
};
```

For efficient use of space, both stacks share the free space between them, so the "stack full" condition is `top1 + 1 == top2`.

Use one temporary stack `tmpStack`. Pop each element `tmp` from the input stack, move back to the input every element of `tmpStack` that is greater than `tmp`, and then push `tmp` on `tmpStack`. At the end `tmpStack` is sorted.

```cpp
stack<int> sortStack(stack<int> &input) {
    stack<int> tmpStack;
    while (!input.empty()) {
        int tmp = input.top();
        input.pop();
        while (!tmpStack.empty() && tmpStack.top() > tmp) {
            input.push(tmpStack.top());
            tmpStack.pop();
        }
        tmpStack.push(tmp);
    }
    return tmpStack;
}

int main() {
    stack<int> input;
    int a[] = {31, 51, 21, 71, 91};
    for (int i = 0; i < 5; i++)
        input.push(a[i]);

    stack<int> sorted = sortStack(input);
    // sorted holds 21, 31, 51, 71, 91 from bottom to top
    return 0;
}
```

**Method 1: make enQueue costly**

i) `enQueue(q, x)` takes $O(n)$:
1. While stack 1 is not empty, push everything from stack 1 to stack 2.
2. Push `x` to stack 1.
3. Push everything back from stack 2 to stack 1.

*Diagram: contents of stack 1 and stack 2 after each step.*

ii) `deQueue(q)` takes $O(1)$:
1. If stack 1 is empty, report an error.
2. Pop an item from stack 1 and return it.

*Diagram: contents of stack 1 after the pop.*

**Method 2: make deQueue costly**

i) `enQueue(q, x)` takes $O(1)$:
1. Push `x` to stack 1.

*Diagram: contents of stack 1 after each push.*

ii) `deQueue(q)` takes $O(n)$:
1. If both stacks are empty, report an error.
2. If stack 2 is empty, while stack 1 is not empty, push everything from stack 1 to stack 2.
3. Pop the element from stack 2 and return it.

