**Circular queue (array implementation)**

```cpp
class Queue {
private:
    int total;
    int *arr;
    int size;
    int front;

public:
    Queue(int cap) {
        total = cap;
        arr = new int[total];
        size = 0;
        front = 0;
    }

    // Insertion
    void enqueue(int item) {
        if (isFull()) {
            cout << "Queue is full";
            return;
        }
        int idx = (front + size) % total;
        arr[idx] = item;
        size++;
    }

    // Deletion
    int dequeue() {
        if (isEmpty()) {
            cout << "Empty";
            return -1;
        }
        int temp = arr[front];
        arr[front] = 0;
        front = (front + 1) % total;
        size--;
        return temp;
    }

    int getFront() {
        if (isEmpty()) {
            cout << "Empty";
            return -1;
        }
        return arr[front];
    }

    bool isEmpty() { return size == 0; }

    bool isFull() { return size == total; }

    void display() {
        for (int i = 0; i < size; i++) {
            int idx = (i + front) % total;
            cout << arr[idx] << endl;
        }
    }
};
```

