int kthFromEnd(int k) {
    Node *s = head;
    Node *f = head;
    for (int i = 0; i < k - 1; i++) {
        f = f->next;
    }
    while (f != tail) {
        s = s->next;
        f = f->next;
    }
    return s->data;
}
```

```c
void removeDuplicates(Node *head)
{
    Node *current = head;
    Node *next_next;
    if (current == NULL) {
        return;
    }
    while (current->next != NULL) {
        if (current->data == current->next->data) {
            next_next = current->next->next;
            free(current->next);
            current->next = next_next;
        } else {
            current = current->next;
        }
    }
}
```

