questions.answer:
Use Floyd's cycle-finding algorithm: `slow` moves one node at a time and `fast` moves two nodes at a time. If the list ends in a cycle they meet; if it is NULL-terminated, `fast` reaches NULL.

```cpp
bool detectCycle(node *&head) {
    node *slow = head;
    node *fast = head;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
        if (fast == slow) {
            return true;
        }
    }
    return false;
}
```

```cpp
struct Node {
    int data;
    Node *next;
    Node(int d) {
        data = d;
        next = NULL;
    }
};

struct Queue {
    Node *front, *rear;

    Queue() {
        front = rear = NULL;
    }

    void enQueue(int x) {
        Node *temp = new Node(x);
        if (rear == NULL) {
            front = rear = temp;
            return;
        }
        rear->next = temp;
        rear = temp;
    }

    void deQueue() {
        if (front == NULL) {
            return;
        }
        Node *temp = front;
        front = front->next;
        if (front == NULL)
            rear = NULL;
        delete temp;
    }
};
```

