*Pseudocode*

```cpp
vector<int> Merge(vector<int>& A, vector<int>& B, vector<int>& C) {
    int i = 0, j = 0, k = 0;
    int m = A.size(), n = B.size(), o = C.size();
    vector<int> D;                       // answer

    // all three lists still have elements
    while (i < m && j < n && k < o) {
        int mn = min({A[i], B[j], C[k]});
        D.push_back(mn);
        // advance the index of the list that gave the minimum
        if (mn == A[i]) i++;
        else if (mn == B[j]) j++;
        else k++;
    }

    // one list has ended: merge the other two
    while (i < m && j < n) {             // C ended
        if (A[i] <= B[j]) D.push_back(A[i++]);
        else D.push_back(B[j++]);
    }
    while (j < n && k < o) {             // A ended
        if (B[j] <= C[k]) D.push_back(B[j++]);
        else D.push_back(C[k++]);
    }
    while (i < m && k < o) {             // B ended
        if (A[i] <= C[k]) D.push_back(A[i++]);
        else D.push_back(C[k++]);
    }

    // two lists have ended: copy what is left of the third
    while (i < m) D.push_back(A[i++]);   // A is left
    while (j < n) D.push_back(B[j++]);   // B is left
    while (k < o) D.push_back(C[k++]);   // C is left
    return D;
}
```

Scan the array and look for positions where `arr[i-1] > arr[i]`.

- At the first such position, set `x = i-1` and `y = i`.
- If a second such position exists, update `y = i`.
- Swap `arr[x]` and `arr[y]`.

```c
void Sort(int arr[], int n) {
    if (n <= 1) return;
    int x = -1, y = -1;
    int prev = arr[0];
    for (int i = 1; i < n; i++) {
        if (prev > arr[i]) {
            if (x == -1) {
                x = i - 1;
                y = i;
            }
            else {
                y = i;
            }
        }
        prev = arr[i];
    }
    swap(arr[x], arr[y]);
}
```

**i) Iterative**

```cpp
bool sorted(int arr[], int n) {
    if (n == 0 || n == 1) {
        return true;
    }
    for (int i = 1; i < n; i++) {
        if (arr[i-1] > arr[i]) {
            return false;
        }
    }
    return true;
}
```

**ii) Recursive**

```cpp
int sorted(int arr[], int n) {
    if (n == 1 || n == 0)
        return 1;
    if (arr[n-1] < arr[n-2])
        return 0;
    return sorted(arr, n - 1);
}
```

**Sorting**

```cpp
bool Same(int arr1[], int arr2[], int m, int n) {
    if (m != n) return false;
    sort(arr1, arr1 + n);
    sort(arr2, arr2 + n);
    for (int i = 0; i < n; i++)
        if (arr1[i] != arr2[i]) return false;
    return true;
}
```

Time $O(n \log n)$, extra space $O(1)$.

**Hashing**

```cpp
bool Same(int arr1[], int arr2[], int n, int m) {
    if (n != m) return false;
    unordered_map<int, int> mp;
    for (int i = 0; i < n; i++) {
        mp[arr1[i]]++;
    }
    for (int i = 0; i < m; i++) {
        if (mp.find(arr2[i]) == mp.end()) return false;
        if (mp[arr2[i]] == 0) return false;
        mp[arr2[i]]--;
    }
    return true;
}
```

Time $O(n)$, extra space $O(n)$.

```cpp
string infixToPostfix(string s) {
    stack<char> st;
    string res;
    for (int i = 0; i < s.length(); i++) {
        if ((s[i] >= '0' && s[i] <= '9') || (s[i] >= 'a' && s[i] <= 'z'))
            res += s[i];                       // operand
        else if (s[i] == '(') {
            st.push(s[i]);
        }
        else if (s[i] == ')') {
            while (!st.empty() && st.top() != '(') {
                res += st.top();
                st.pop();
            }
            if (!st.empty()) {
                st.pop();                      // remove '('
            }
        }
        else {                                 // operator
            while (!st.empty() && prec(st.top()) >= prec(s[i])) {
                res += st.top();
                st.pop();
            }
            st.push(s[i]);
        }
    }
    // pop the remaining operators into the result
    while (!st.empty()) {
        res += st.top();
        st.pop();
    }
    return res;
}
```

Here `prec()` returns the precedence of an operator, and it returns the lowest value for `(`.

